import json
from pathlib import Path

from mock_api import TRACE, search
from query_audit import build_rejection
from timezone_defaults import DEFAULT_TIMEZONE
from window_projection import parse_bound


def _normalized_value(value):
    """Return the value used for comparison, including the naive-time policy."""
    parsed = parse_bound(value)
    return parsed, parsed.astimezone(DEFAULT_TIMEZONE)


def _normalization_report(start, end=None):
    report = {
        "default_timezone": "UTC",
        "start_utc": start.isoformat(),
    }
    if end is not None:
        report["end_utc"] = end.isoformat()
    return report


def _range_error(message, payload, normalized):
    error = build_rejection("date_range", message, payload)
    error["normalized"] = normalized
    return error


def _is_fall_back_overlap(start, end):
    """Identify the ambiguous local ordering rejected by the migration contract."""
    start_local = start.replace(tzinfo=None)
    end_local = end.replace(tzinfo=None)
    return (
        start_local.date() == end_local.date()
        and start_local.hour == end_local.hour
        and start_local > end_local
        and start.utcoffset() != end.utcoffset()
    )


def validate_range(payload):
    if not isinstance(payload, dict):
        return [build_rejection("query", "must be an object", payload)]

    errors = []
    parsed = {}
    normalized = {}

    for param in ("start_date", "end_date"):
        if param == "end_date" and param not in payload:
            continue
        if param not in payload:
            errors.append(build_rejection(param, "is required", payload))
            continue
        value = payload[param]
        if not isinstance(value, str):
            errors.append(build_rejection(param, "must be an ISO 8601 string", payload))
            continue
        try:
            parsed[param], normalized[param] = _normalized_value(value)
        except (TypeError, ValueError):
            errors.append(build_rejection(param, "must be a valid ISO 8601 timestamp", payload))

    if "start_date" not in parsed or "end_date" not in parsed:
        return errors

    start = parsed["start_date"]
    end = parsed["end_date"]
    start_utc = normalized["start_date"]
    end_utc = normalized["end_date"]
    report = _normalization_report(start_utc, end_utc)

    if end_utc < start_utc:
        errors.append(_range_error(
            "end_date must be on or after start_date after UTC normalization",
            payload,
            report,
        ))

    if _is_fall_back_overlap(start, end):
        errors.append(_range_error(
            "ambiguous fall-back DST range: local end clock is earlier than local start clock",
            payload,
            report,
        ))

    return errors


def process_queries(path):
    TRACE.clear()
    payload = json.loads(Path(path).read_text(encoding="utf-8"))
    accepted = []
    rejected = []
    for index, query in enumerate(payload):
        errors = validate_range(query)
        if errors:
            rejected.append({"index": index, "errors": errors, "original": query})
            continue
        accepted.append(search(query))
    return {"accepted": accepted, "rejected": rejected, "trace": list(TRACE)}

